//! Security Hypothesis Model (v0.5 Strategic VulnLLM Layer)
//!
//! Represents structured security hypotheses generated by VulnLLM reasoning over the
//! attack surface graph.
//!
//! CRITICAL RULE: A hypothesis is NOT a finding. Hypotheses represent potential vulnerability
//! models that guide strategic prioritization and must be proven with empirical evidence.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum HypothesisStatus {
    Pending,
    Investigating,
    Validated,
    Refuted,
    Unverified,
}

impl Default for HypothesisStatus {
    fn default() -> Self {
        HypothesisStatus::Pending
    }
}

impl HypothesisStatus {
    pub fn as_str(&self) -> &'static str {
        match self {
            HypothesisStatus::Pending => "pending",
            HypothesisStatus::Investigating => "investigating",
            HypothesisStatus::Validated => "validated",
            HypothesisStatus::Refuted => "refuted",
            HypothesisStatus::Unverified => "unverified",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SecurityHypothesis {
    pub id: Uuid,
    pub investigation_id: Uuid,
    pub category: String,
    pub target: String,
    pub rationale: String,
    pub confidence: f64,
    pub suggested_actions: Vec<String>,
    pub required_evidence: Vec<String>,
    pub status: String,
    pub created_at: DateTime<Utc>,
    pub resolved_at: Option<DateTime<Utc>>,
}

impl SecurityHypothesis {
    pub fn new(
        investigation_id: Uuid,
        category: impl Into<String>,
        target: impl Into<String>,
        rationale: impl Into<String>,
        confidence: f64,
        suggested_actions: Vec<String>,
        required_evidence: Vec<String>,
    ) -> Self {
        Self {
            id: Uuid::new_v4(),
            investigation_id,
            category: category.into(),
            target: target.into(),
            rationale: rationale.into(),
            confidence: confidence.clamp(0.0, 1.0),
            suggested_actions,
            required_evidence,
            status: HypothesisStatus::Pending.as_str().to_string(),
            created_at: Utc::now(),
            resolved_at: None,
        }
    }

    pub fn mark_validated(&mut self) {
        self.status = HypothesisStatus::Validated.as_str().to_string();
        self.resolved_at = Some(Utc::now());
    }

    pub fn mark_refuted(&mut self) {
        self.status = HypothesisStatus::Refuted.as_str().to_string();
        self.resolved_at = Some(Utc::now());
    }

    pub fn mark_unverified(&mut self) {
        self.status = HypothesisStatus::Unverified.as_str().to_string();
        self.resolved_at = Some(Utc::now());
    }
}
